import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"クイックスタート","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/getting-started.md","filePath":"ja-JP/user-guide/getting-started.md","lastUpdated":1787982919000}'),l={name:"ja-JP/user-guide/getting-started.md"};function d(n,t,i,s,c,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="クイックスタート" tabindex="-1">クイックスタート <a class="header-anchor" href="#クイックスタート" aria-label="Permalink to &quot;クイックスタート&quot;">​</a></h1><p>Lertaro へようこそ！Lertaro は、Windows 向けに高度に最適化された超高速ファイル検索＆生産性向上ランチャーです。このガイドでは、インストール方法、コアアーキテクチャ、3 つのウィンドウ形態、および基本的な検索操作について説明します。</p><h2 id="_1-ダウンロードとインストール" tabindex="-1">1. ダウンロードとインストール <a class="header-anchor" href="#_1-ダウンロードとインストール" aria-label="Permalink to &quot;1. ダウンロードとインストール&quot;">​</a></h2><p>公式サイトのトップページから最新バージョンを入手できます。各リリースでは、ネイティブ <strong>x64</strong> および <strong>ARM64</strong> アプリケーション用のインストーラー版とポータブル版が提供されます。</p><h3 id="インストーラー版-lertaro-setup-exe、推奨" tabindex="-1">インストーラー版（<code>Lertaro-Setup.exe</code>、推奨） <a class="header-anchor" href="#インストーラー版-lertaro-setup-exe、推奨" aria-label="Permalink to &quot;インストーラー版（`Lertaro-Setup.exe`、推奨）&quot;">​</a></h3><ul><li><strong>自動セットアップ</strong>：インストールウィザードがバックグラウンドインデックスサービス（<code>Lertaro.Service</code>）の登録、スタートアップ登録、および必要な .NET Desktop Runtime の検出とインストールを自動的に行います。</li><li><strong>スムーズな更新</strong>：バックグラウンドでの自動更新チェックとワンクリックでの上書きアップデートに対応しています。</li></ul><h3 id="ポータブル版-lertaro-portable-zip" tabindex="-1">ポータブル版（<code>Lertaro-Portable.zip</code>） <a class="header-anchor" href="#ポータブル版-lertaro-portable-zip" aria-label="Permalink to &quot;ポータブル版（`Lertaro-Portable.zip`）&quot;">​</a></h3><ul><li><strong>解凍してすぐ実行</strong>：任意のフォルダーに解凍するだけで直接実行でき、インストールは不要です。</li><li><strong>ランタイムの追加</strong>：システムに必要な .NET Desktop Runtime が未導入の場合は、解凍先にある <code>install-dotnet-runtime.bat</code> を実行してインストールしてください。</li><li><strong>データの分離と自己完結</strong>：ポータブル版は、マシン全体の設定をアプリと同じディレクトリの <code>Data\\Machine</code> に、ユーザーごとの個別設定を <code>Data\\Users\\&lt;SID hash&gt;</code> に保存します。<code>Data</code> ディレクトリが未作成の場合は互換性のためにシステムの <code>%ProgramData%\\Lertaro</code> や <code>%LocalAppData%\\Lertaro</code> を参照しますが、一度フォルダーが作成されると完全に自己完結したポータブル環境として動作します。</li><li><strong>完全なクリーンアップ</strong>：ポータブル版が不要になった場合は、フォルダーを削除する前に同梱の <code>portable-cleanup.bat</code> を実行してください。バックグラウンドサービスを停止・削除し、ユーザーの <code>lertaro://</code> URI プロトコルやスタートアップ登録をクリーンに削除します。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Surface Pro X や Snapdragon 搭載ノート PC などの Windows on ARM デバイスをご利用の場合は、ネイティブの <code>Lertaro-Setup-arm64.exe</code> または <code>Lertaro-Portable-arm64.zip</code> をダウンロードすることで、最高のパフォーマンスと省電力性を得られます。</p></div><h2 id="_2-コアアーキテクチャの概要" tabindex="-1">2. コアアーキテクチャの概要 <a class="header-anchor" href="#_2-コアアーキテクチャの概要" aria-label="Permalink to &quot;2. コアアーキテクチャの概要&quot;">​</a></h2><p>Lertaro を初めて起動すると、専用の Windows バックグラウンドサービス（<code>Lertaro.Service</code>）が自動的にインストールされ起動します。この設計を理解しておくと、より快適に使いこなせます。</p><ul><li><strong>フォアグラウンド App（UI・対話層）</strong>：検索ウィンドウ、フローティングパネル、アクションメニュー、キーフック、プレビューの描画を担当します。メモリ消費を最小限に抑え、常にミリ秒未満の即時応答性を維持します。</li><li><strong>バックグラウンド Service（インデックス・データ層）</strong>：システムサービス権限で常駐し、NTFS / ReFS の USN 変更ジャーナルの監視、その他のファイルシステムのリアルタイム変更の検知、ネットワーク共有インデックスの管理、インメモリ検索ツリーの高速保持を行います。</li><li><strong>アーキテクチャの利点</strong>：UI の再起動や更新を行ってもバックグラウンドのインデックスが失われたり全スキャンが再実行されたりすることはありません。また、大容量ディスクのインデックス処理が UI の快適なタイピングを妨げることもありません。<a href="./settings/service-status.html"><strong>設定 → サービス状態</strong></a> でいつでも稼働状況を確認できます。</li></ul><h2 id="_3-3-つのウィンドウ形態" tabindex="-1">3. 3 つのウィンドウ形態 <a class="header-anchor" href="#_3-3-つのウィンドウ形態" aria-label="Permalink to &quot;3. 3 つのウィンドウ形態&quot;">​</a></h2><p>Lertaro には固定された単一のウィンドウだけでなく、ワークフローに応じた 3 つのウィンドウ形態が用意されています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">ウィンドウ形態</th><th style="text-align:left;">既定の呼び出し方法</th><th style="text-align:left;">主な特徴と設計コンセプト</th><th style="text-align:left;">最適な利用シーン</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>クイックウィンドウ（Quick Window）</strong></td><td style="text-align:left;"><code>Ctrl</code> キーの 2 回連打（変更可能）</td><td style="text-align:left;">画面中央に素早く現れるコンパクトなポップアップ。数字キーによるダイレクト選択や完全なキーボード操作に最適化</td><td style="text-align:left;">アプリの高速起動、特定ファイルの即時検索、計算機や翻訳の利用</td></tr><tr><td style="text-align:left;"><strong>メインウィンドウ（Full Window）</strong></td><td style="text-align:left;">タスクバー/スタートメニュー、または <code>Ctrl+F</code></td><td style="text-align:left;">大画面のフル機能ウィンドウ。膨大な結果のテーブル表示、サイドバーフィルター、列ソート、内蔵ストレージ分析機能に対応</td><td style="text-align:left;">ディープなファイル探索、大容量ディスクの整理、高度な条件絞り込み</td></tr><tr><td style="text-align:left;"><strong>インラインウィンドウ（Inline Window）</strong></td><td style="text-align:left;">ファイル選択ダイアログやエクスプローラーに自動埋め込み</td><td style="text-align:left;">Windows 標準のダイアログや対応ファイラーにシームレスに組み込まれ、作業中の画面を離れずに検索可能</td><td style="text-align:left;">アプリの「開く」「名前を付けて保存」画面で目的のフォルダーやファイルを即座に指定</td></tr></tbody></table><p>3 つのウィンドウ形態は、まったく同一の検索エンジン、ショートカット体系、フィルター規則、アクションメニューを共有しています。</p><h2 id="_4-初めての検索と基本操作" tabindex="-1">4. 初めての検索と基本操作 <a class="header-anchor" href="#_4-初めての検索と基本操作" aria-label="Permalink to &quot;4. 初めての検索と基本操作&quot;">​</a></h2><h3 id="入力して即座に検索" tabindex="-1">入力して即座に検索 <a class="header-anchor" href="#入力して即座に検索" aria-label="Permalink to &quot;入力して即座に検索&quot;">​</a></h3><p>検索ウィンドウを開いたら、キーボードからそのまま文字を入力するだけです。ミリ秒単位の即時性で結果がリアルタイムに表示されます。検索アルゴリズムは既定であいまい一致を採用しており、連続していない文字飛びでも正確にヒットします。詳しくは <a href="./search-syntax.html"><strong>検索構文</strong></a> をご覧ください。</p><h3 id="結果の選択と起動" tabindex="-1">結果の選択と起動 <a class="header-anchor" href="#結果の選択と起動" aria-label="Permalink to &quot;結果の選択と起動&quot;">​</a></h3><ul><li><strong>項目の移動</strong>：方向キー <code>↑</code> / <code>↓</code>（または設定されたナビゲーションキー <code>Ctrl+P</code> / <code>Ctrl+N</code>）で一覧の選択項目を上下に移動します。</li><li><strong>直接開く</strong>：<code>Enter</code> キーを押して、選択したファイルを開くかアプリケーションを起動します。</li><li><strong>エクスプローラーで表示</strong>：<code>Ctrl+Enter</code> を押すと、エクスプローラーが開き対象ファイルが選択された状態で表示されます。</li><li><strong>管理者として実行</strong>：<code>Ctrl+Shift+Enter</code> を押すと、管理者権限で実行します。</li><li><strong>数字キーによる直接起動</strong>：クイックウィンドウでは、<code>Ctrl</code> + <code>1</code>〜<code>9</code> を押すことで上位 9 件の結果を直接開くことができます。</li></ul><h3 id="アクションメニューと拡張操作" tabindex="-1">アクションメニューと拡張操作 <a class="header-anchor" href="#アクションメニューと拡張操作" aria-label="Permalink to &quot;アクションメニューと拡張操作&quot;">​</a></h3><p>選択中の項目で <code>Ctrl+O</code> または方向キー <code>→</code> を押すと、充実した <strong>アクションメニュー</strong> が開き、パスのコピー、プロパティ確認、ファイル操作、プラグイン拡張コマンドなどを実行できます。詳しくは <a href="./actions-and-preview.html"><strong>アクションとプレビュー</strong></a> および <a href="./hotkeys.html"><strong>ホットキー</strong></a> を参照してください。</p>',23)])])}const p=e(l,[["render",d]]);export{u as __pageData,p as default};
